  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can distinguish current from potential difference and explain why current is conserved at a junction and why potential differences sum to zero around a loop, then solve a small set of course-style circuit problems correctly using those ideas."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
          "explanation": "The outcome is conceptual clarity plus the ability to solve circuits independently. There is no deadline and no verified assessment, so I work backwards from the accepted goal: rebuild the current/potential-difference distinction, connect it to conservation, then apply it in problems. With no readiness evidence, I treat the learner as a beginner and start from the definitions and the physical meaning, not from formulas. I integrate explanation and supported application into a small number of activities rather than a ritual learn/practice/check cycle. Remediation is contingent on an observed failure in the integrated task, so the default path stays short and ends early if the task succeeds.",
          "recommendedEffort": {
            "lowMinutes": 80,
            "likelyMinutes": 130,
            "highMinutes": 200
          },
          "phases": [
            {
              "localId": "foundation",
              "title": "Distinguish current from potential difference",
              "outcome": "Explain in your own words what current is, what potential difference is, and why they are different quantities with different units and different roles in a circuit.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 50,
                "highMinutes": 80
              },
              "readinessCriterion": "You can give a correct, self-generated statement of each quantity and correctly label which is which in a simple circuit."
            },
            {
              "localId": "conservation",
              "title": "Why circuit rules hold",
              "outcome": "Explain why current is conserved at a junction and why potential differences around a loop sum to zero, using the underlying conservation ideas.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 40,
