            "lowMinutes": 40,
            "likelyMinutes": 60,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "phase_core",
              "title": "Bayes' rule: explanation and transfer",
              "outcome": "Explain Bayes' rule and apply it correctly to a changed medical-test example, keeping base rate distinct from sensitivity.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
