{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "All three assigned linear equations with parentheses are solved, each expansion of a negative is explained, and every answer is checked by substitution."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "Complete and understand a short homework set of three linear equations with parentheses. I make sign errors when expanding negatives.",
          "explanation": "The accepted outcome is a bounded homework set, not a mastery course. One integrated committed activity covers solving the three equations, explaining the negative-expansion rule while working, and checking each answer by substitution. Because the specific three equations were not supplied in the context, the learner will write them from the assignment; if the assignment is unavailable, they use the three practice equations given in the instructions. A contingent remediation activity is triggered only if a sign error actually appears in the checked work, so no unnecessary preparation is booked. No separate transfer exercise is added because the three assigned equations already provide varied contexts and the stopping point is finishing the correctly explained and checked assignment.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 60
          },
          "phases": []
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Applying the negative-expansion rule to parentheses is the diagnosed weakness and is addressed directly in the committed homework activity."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Solving the three linear equations is the assigned homework and the core of the committed activity."
          }
        ],
        "activities": [
          {
            "localId": "homework_set",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Solve, explain and check three linear equations with parentheses",
            "activityType": "Assigned homework completion with explanation",
            "purpose": "Complete the assigned homework set while explicitly addressing the negative-expansion weakness and verifying every answer.",
            "instructions": "Write down the three linear equations with parentheses from your assignment. If you do not have the assignment sheet, use these three equations:\n1) 2(x - 3) = 10\n2) -3(x + 4) = 9\n3) 5 - 2(x - 1) = 11\n\nFor each equation:\n- Expand the parentheses step by step. When a negative sign multiplies a parenthesis, say or write the rule you are using (for example, '-2 times (x - 1) means subtract 2x and add 2').\n- Solve for x, showing the inverse operations.\n- Check your answer by substituting it back into the original equation and confirming both sides are equal.\n\nAfter finishing all three, write one or two sentences describing the sign rule you used when expanding negatives, and note any step where you were unsure. If an answer fails the check, find and correct the sign error before moving on.",
            "completionCriterion": "All three equations are solved, each negative expansion is accompanied by an explanation of the sign rule, every answer is verified by substitution, and any failed check is corrected.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "sign_remediation",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted negative-expansion repair",
            "activityType": "Error-triggered remediation",
            "purpose": "Repair the specific sign error observed in the committed homework before the learner moves on.",
            "instructions": "Review the step where the sign error occurred. Re-explain the rule: when a negative number multiplies a parenthesis, every term inside changes sign. Work through two similar expansions (for example, -4(x - 2) and -(3x + 5)), then re-solve the one equation from the homework that failed, checking the answer again.",
            "completionCriterion": "The previously failed equation is solved correctly with a verified substitution, and the learner correctly expands two similar negative-parenthesis expressions.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 20,
              "highMinutes": 30
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "homework_set",
                "condition": "A sign error is found during the check of any of the three equations."
              }
            },
            "hardDependencies": [
              "homework_set"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The three specific equations from the assignment were not supplied in the context; the learner will use the assignment sheet if available or the three practice equations in the instructions."
          ],
          "tradeOffs": [
            "No separate transfer or extra practice set is committed because the assigned homework already provides varied examples and the accepted outcome is bounded to completing and understanding that set.",
            "The contingent remediation is kept small and failure-triggered so it does not extend the assignment unnecessarily."
          ],
          "unresolvedUncertainty": [
            "The exact equations in the assignment are unknown; if they differ in difficulty from the practice equations, the effort estimate may need adjustment."
          ],
          "stoppingConditions": [
            "Stop when all three equations are solved, explained and checked, and any observed sign error has been corrected."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "This plan commits only the assigned homework as one integrated activity, with a small contingent repair only if a sign error actually appears. It does not add a compulsory second set or transfer exercise, because the three equations already give varied practice and the accepted outcome is bounded to completing and understanding the homework. The main uncertainty is the exact equations, which the learner will supply from the assignment or from the provided practice set."
}

