  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can loop over a small list of expense dictionaries, accumulate totals in a dictionary, and print a correct totals result — the shared prerequisite demonstrated once."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare both a CSV report and a JSON report. I am new to Python loops and dictionaries. A shared loops/dictionary prerequisite should have one owner and count once.",
          "explanation": "The two targets share one genuine prerequisite: looping over records and accumulating results in a dictionary. Because the learner is new to both loops and dictionaries, the useful next checkpoint is not the final CSV report but a single small integrated task that teaches and demonstrates that prerequisite once. plan_1 owns this shared prerequisite; plan_2 depends on it rather than duplicating it. The CSV report itself stays strategic until the prerequisite is demonstrated; it is not booked now. Empty readiness records are uncertainty, not evidence of prior mastery, so the prerequisite task includes a short taught explanation before the learner writes any loop or dictionary code.",
          "recommendedEffort": {
            "lowMinutes": 25,
            "likelyMinutes": 40,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "phase_shared_prereq",
              "title": "Shared loops and dictionary prerequisite",
              "outcome": "The learner can loop over a list of expense dictionaries and accumulate per-category totals in a dictionary, demonstrated on a small worked example.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 40,
                "highMinutes": 60
              },
              "readinessCriterion": "The learner independently writes and runs a loop that reads each expense dictionary, adds its amount into a totals dictionary keyed by category, and prints the totals correctly."
            },
            {
              "localId": "phase_csv_report",
              "title": "CSV totals report (strategic, unbooked)",
              "outcome": "A CSV totals report produced from the same loops/dictionary prerequisite.",
              "readinessCriterion": "The prerequisite checkpoint is independently demonstrated and the learner requests the next expansion."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The shared loops-and-dictionaries prerequisite is taught and demonstrated once here; plan_2 reuses this same owned work instead of duplicating it."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The CSV totals report is the eventual plan_1 deliverable; it remains strategic and unbooked until the shared prerequisite checkpoint is demonstrated."
          }
        ],
        "activities": [
          {
            "localId": "shared_prereq",
            "outcomeRefs": [
              "phase_shared_prereq"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Learn and demonstrate loops and dictionary totals on a small expense list",
            "activityType": "Guided beginner programming task",
            "purpose": "Teach the one shared prerequisite (looping over records and accumulating dictionary totals) and demonstrate it once, so plan_2 can depend on the same owned work without duplicating it.",
            "instructions": "Work through this in one sitting. Use this small list of expenses as your data (type it in yourself):\nexpenses = [\n  {\"category\": \"food\", \"amount\": 12},\n  {\"category\": \"travel\", \"amount\": 20},\n  {\"category\": \"food\", \"amount\": 8},\n  {\"category\": \"books\", \"amount\": 15},\n]\nStep 1 — Teach yourself the two constructs you need. A for loop visits each item in a list one at a time: for e in expenses: ... . A dictionary stores key→value pairs; totals[\"food\"] = totals.get(\"food\", 0) + e[\"amount\"] adds to the running total for that category, creating the key with 0 if it is not there yet. Read that explanation carefully before writing code.\nStep 2 — Write a loop that goes through every expense dictionary, reads its \"category\" and \"amount\", and accumulates the amount into a totals dictionary keyed by category.\nStep 3 — After the loop, print the totals dictionary and also print each category with its total on its own line.\nStep 4 — Run your code and check the output against the expected totals: food 20, travel 20, books 15. If a number is wrong, find the line that caused it, explain the mistake to yourself, and fix it.\nDo not use any library or method beyond the loop and dictionary operations shown above; those are all you need for this checkpoint.",
            "completionCriterion": "Your program runs and prints totals food 20, travel 20, books 15, and you can point to the line in your loop that accumulates each amount into the dictionary.",
            "effort": {
              "lowMinutes": 25,
              "likelyMinutes": 40,
              "highMinutes": 60
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has Python installed and can run a .py file or a REPL.",
            "No prior loop or dictionary experience is assumed; the activity teaches both constructs before use."
          ],
          "tradeOffs": [
            "The CSV report is deliberately not booked now: booking it before the shared prerequisite is demonstrated would either duplicate the prerequisite or skip it.",
            "The activity is one integrated task rather than separate learn/practice/check stages, because the bounded goal is a single demonstrated capability."
          ],
          "unresolvedUncertainty": [
            "Whether the learner can already run Python; if not, a short setup step may be needed before this activity."
          ],
          "stoppingConditions": [
            "Stop when the totals print correctly and the learner can explain the accumulation line; do not proceed to the CSV report without a fresh request."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report with the same loops/dictionary prerequisite as the CSV target. Do not duplicate prerequisite work; use its owning Plan.",
          "explanation": "plan_2's only genuine prerequisite is the shared loops-and-dictionary capability owned by plan_1. Because that prerequisite has no booked activity under plan_2, plan_2 books no activity now: its useful next checkpoint is reached by completing plan_1's shared_prereq, after which the JSON report can be built using the same demonstrated capability. The JSON report itself remains strategic and unbooked until the prerequisite works and the learner requests expansion.",
          "recommendedEffort": {
            "lowMinutes": 0,
            "likelyMinutes": 0,
            "highMinutes": 0
          },
          "phases": [
            {
              "localId": "phase_json_report",
              "title": "JSON expenses report (strategic, unbooked)",
              "outcome": "A JSON expenses report produced using the shared loops/dictionary prerequisite owned by plan_1.",
              "readinessCriterion": "plan_1's shared_prereq checkpoint is independently demonstrated and the learner requests the next expansion."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "plan_2 relies on the same loops-and-dictionaries prerequisite, which is taught and owned once by plan_1's shared_prereq activity; plan_2 does not duplicate it."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report is the eventual plan_2 deliverable; it remains strategic and unbooked until the shared prerequisite is demonstrated."
          }
        ],
        "activities": [],
        "decisions": {
          "assumptions": [
            "The shared loops-and-dictionary prerequisite is genuinely identical for both reports, so one owning activity suffices."
          ],
          "tradeOffs": [
            "No activity is booked under plan_2 now: booking one would either duplicate plan_1's prerequisite or start the JSON report before its prerequisite is demonstrated."
          ],
          "unresolvedUncertainty": [
            "Whether the JSON report will need any additional construct (for example json.dumps) beyond the shared prerequisite; that will be assessed after the prerequisite checkpoint."
          ],
          "stoppingConditions": [
            "Stop when plan_1's shared_prereq is demonstrated; the JSON report waits for a fresh request."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "shared_prereq"
      },
      "dependent": {
        "planRef": "plan_2",
