providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "A working Python script that reads a small expenses CSV, groups amounts by category, reports each total, and detects and explains malformed rows; then independently demonstrated on a changed CSV you create."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
